import { STATUS_CODES as NODE_STATUS_CODES } from 'node:http';

/**
 * Lookup table of HTTP status codes to their standard reason phrases,
 * keyed by numeric code (e.g. 404 -> "Not Found").
 *
 * Sourced from Node's built-in table, which tracks the IANA HTTP Status
 * Code Registry, so it stays current with the runtime.
 */
export const STATUS_CODES = Object.freeze(
  Object.fromEntries(
    Object.entries(NODE_STATUS_CODES).map(([code, phrase]) => [Number(code), phrase]),
  ),
);

/** Returns the reason phrase for a status code, or undefined if unknown. */
export function reasonPhrase(code) {
  return STATUS_CODES[code];
}

/** Returns true if the code has a registered reason phrase. */
export function isKnownStatus(code) {
  return Object.hasOwn(STATUS_CODES, code);
}
EOF
cat > src/server.js <<'EOF'
import { createServer } from 'node:http';
import { pathToFileURL } from 'node:url';
import { STATUS_CODES, reasonPhrase, isKnownStatus } from './status-codes.js';

function sendJson(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

export function handler(req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');

  if (req.method !== 'GET') {
    return sendJson(res, 405, { error: reasonPhrase(405) });
  }

  if (pathname === '/status-codes') {
    return sendJson(res, 200, STATUS_CODES);
  }

  const match = pathname.match(/^\/status-codes\/(\d{3})$/);
  if (match) {
    const code = Number(match[1]);
    if (!isKnownStatus(code)) {
      return sendJson(res, 404, { error: `Unknown status code: ${code}` });
    }
    return sendJson(res, 200, { code, reason: reasonPhrase(code) });
  }

  return sendJson(res, 404, { error: reasonPhrase(404) });
}

export function createApp() {
  return createServer(handler);
}

// Start listening only when run directly (not when imported by tests).
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, () => {
    console.log(`Server listening on http://localhost:${port}`);
  });
}
EOF
cat > test/status-codes.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { STATUS_CODES, reasonPhrase, isKnownStatus } from '../src/status-codes.js';

test('maps common codes to standard reason phrases', () => {
  assert.equal(reasonPhrase(200), 'OK');
  assert.equal(reasonPhrase(201), 'Created');
  assert.equal(reasonPhrase(204), 'No Content');
  assert.equal(reasonPhrase(301), 'Moved Permanently');
  assert.equal(reasonPhrase(400), 'Bad Request');
  assert.equal(reasonPhrase(404), 'Not Found');
  assert.equal(reasonPhrase(500), 'Internal Server Error');
  assert.equal(reasonPhrase(503), 'Service Unavailable');
});

test('unknown codes return undefined', () => {
  assert.equal(reasonPhrase(299), undefined);
  assert.equal(isKnownStatus(299), false);
  assert.equal(isKnownStatus(418), true);
});

test('table is frozen and keyed by number', () => {
  assert.ok(Object.isFrozen(STATUS_CODES));
  assert.throws(() => { STATUS_CODES[200] = 'Changed'; }, TypeError);
});
EOF
cat > test/server.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from '../src/server.js';

let server;
let base;

before(async () => {
  server = createApp();
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
});

after(() => server.close());

test('GET /status-codes/:code returns the reason phrase', async () => {
  const res = await fetch(`${base}/status-codes/404`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { code: 404, reason: 'Not Found' });
});

test('GET /status-codes/:code with unknown code returns 404', async () => {
  const res = await fetch(`${base}/status-codes/299`);
  assert.equal(res.status, 404);
});

test('GET /status-codes returns the full table', async () => {
  const res = await fetch(`${base}/status-codes`);
  const body = await res.json();
  assert.equal(body['200'], 'OK');
  assert.equal(body['503'], 'Service Unavailable');
});

test('non-GET methods return 405', async () => {
  const res = await fetch(`${base}/status-codes`, { method: 'POST' });
  assert.equal(res.status, 405);
});
EOF
cat > README.md <<'EOF'
# http-server

A minimal Node.js HTTP server with a lookup table of HTTP status codes and their standard reason phrases. No dependencies.

## Usage

```sh
npm start          # listens on PORT (default 3000)
npm run dev        # restart on file changes
npm test
```

## Endpoints

| Method | Path                  | Response                                  |
| ------ | --------------------- | ----------------------------------------- |
| GET    | `/status-codes`       | Full table: `{ "200": "OK", ... }`        |
| GET    | `/status-codes/:code` | `{ "code": 404, "reason": "Not Found" }`  |

## Lookup table

```js
import { STATUS_CODES, reasonPhrase, isKnownStatus } from './src/status-codes.js';

reasonPhrase(404);   // "Not Found"
isKnownStatus(299);  // false
```

The table comes from Node's built-in `http.STATUS_CODES` (which follows the IANA registry). It's re-exported with numeric keys and frozen.
EOF
